// LIB-2d parity check, local only: runs the production recognition sandbox over the 86 evaluation pages generated by
// scripts/lib-2d-ocr-eval (node gen.mjs set && node gen2.mjs set) and scores them with that tool's metrics.
// Run: OCR_PARITY=1 pnpm --filter web exec vitest run src/lib/library-sandbox/__tests__/ocr-parity.browser.test.ts
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { afterAll, beforeAll, expect, it } from 'vitest';
import { startHarness, type Harness } from './browser-harness';
import type { OcrPage } from '../ocr/types';

const EVAL = new URL('../../../../../../scripts/lib-2d-ocr-eval/', import.meta.url);
const enabled = process.env.OCR_PARITY === '1' && existsSync(new URL('set/manifest-2.json', EVAL));
let harness: Harness;

beforeAll(async () => { if (enabled) harness = await startHarness(); }, 120_000);
afterAll(async () => { await harness?.close(); }, 30_000);

it.skipIf(!enabled)('matches the evaluated accuracy on all evaluation pages', async () => {
  const { score } = await import(new URL('metrics.mjs', EVAL).href) as {
    score(a: string, b: string): { refLen: number; edits: number } };
  const manifest = ['set/manifest.json', 'set/manifest-2.json'].flatMap((file) =>
    JSON.parse(readFileSync(new URL(file, EVAL), 'utf8')) as Array<{ id: string; cat: string }>);
  for (const { id } of manifest) harness.samples.set(id, readFileSync(new URL(`set/${id}.jpg`, EVAL)));
  const page = await harness.open();
  const rows: Array<{ id: string; cat: string; refLen: number; edits: number; ms: number; flipped: boolean }> = [];
  for (let i = 0; i < manifest.length; i += 8) {
    const batch = manifest.slice(i, i + 8);
    const outcome = await page.evaluate((names) => (window as unknown as { sandboxTest: {
      recognizeSamples(n: string[]): Promise<{ ok: boolean; value?: OcrPage[] }> } }).sandboxTest.recognizeSamples(names),
    batch.map((m) => m.id));
    expect(outcome.ok).toBe(true);
    outcome.value!.forEach((result, k) => {
      const ok = result.ok ? result : { text: '', ms: 0, flipped: false };
      const s = score(readFileSync(new URL(`set/${batch[k]!.id}.txt`, EVAL), 'utf8'), ok.text);
      rows.push({ id: batch[k]!.id, cat: batch[k]!.cat, refLen: s.refLen, edits: s.edits, ms: ok.ms, flipped: ok.flipped });
    });
  }
  writeFileSync(new URL('results/product-parity.json', EVAL), JSON.stringify(rows, null, 1));
  const acc = (r: typeof rows) => 1 - r.reduce((a, x) => a + x.edits, 0) / r.reduce((a, x) => a + x.refLen, 0);
  const step1 = rows.filter((r) => r.id.startsWith('p')), step2 = rows.filter((r) => r.id.startsWith('q'));
  console.log(JSON.stringify({ step1: acc(step1), step2: acc(step2), below95: rows.filter((r) => 1 - r.edits / r.refLen < 0.95).map((r) => r.id),
    meanMs: rows.reduce((a, r) => a + r.ms, 0) / rows.length, maxMs: Math.max(...rows.map((r) => r.ms)) }));
  expect(acc(step1)).toBeGreaterThanOrEqual(0.99);
  expect(acc(step2)).toBeGreaterThanOrEqual(0.99);
}, 1_800_000);
